candidates.raw:
    adcs_status_t status = ADCS_OK;
    double d[3];
    double mag[3];
    unint32 sat_mask = 0U;
    int i;

    /* Input validation */
    if ((requested_a_m2 == NULL) || (duty == NULL)) {
        duty->command = (adcs_vec3_t){0.0, 0.0, 0.0};
        duty->saturated_axes = 0U;
        return ADCS_E_NULL;
    }
    if (!isfinite(full_scale_a_m2) || !isfinite(minimum_duty) ||
        full_scale_a_m2 <= 0.0 || minimum_duty < 0.0 || minimum_duty > 1.0) {
        duty->command = (adcs_vec3_t){0.0, 0.0, 0.0};
        duty->saturated_axes = 0U;
        return ADCS_E_RANGE;
    }

    /* Process each axis */
    for (i = 0; i < 3; i++) {
        double req_val;
        switch (i) {
            case 0: req_val = requested_a_m2->x; break;
            case 1: req_val = requested_a_m2->y; break;
            case 2: req_val = requested_a_m2->z; break;
            default: req_val = 0.0; break; 
        }

        d[i] = req_val / full_scale_a_m2;

        /* Determine magnitude based on normalized decision table */
        if (d[i] == 0.0) {
            mag[i] = 0.0;
            /* Promotion bit clear */
        } else {
            double abs_d = fabs(d[i]);
            if (abs_d < minimum_duty) {
                mag[i] = minimum_duty;
                /* Set promotion bit for this axis */
                sat_mask |= (unint32)(1U << i);
            } else if (abs_d <= 1.0) {
                mag[i] = abs_d;
                /* Promotion bit clear */
            } else {
                mag[i] = 1.0;
                /* Promotion bit clear */
            }
        }

        /* Restore original sign */
        if (req_val < 0.0) {
            mag[i] = -mag[i];
        }
    }

    /* Output assignment */
    duty->command.x = mag[0];
    duty->command.y = mag[1];
    duty->command.z = mag[2];
    duty->saturated_axes = sat_mask;

    return ADCS_OK;
}

