candidates.raw:
    adcs_vec3_t cmd_vec;
    unint32 mask;
    double d, abs_d, out_mag;
    size_t i;
    double vals[3];

    /* 1. Null check */
    if ((requested_a_m2 == NULL) || (duty == NULL)) {
        return ADCS_E_NULL;
    }

    /* 2. Invalid numeric input check */
    if ((!adcs_is_finite_vec3(requested_a_m2)) || 
        (!isfinite(full_scale_a_m2)) || 
        (!isfinite(minimum_duty)) || 
        (full_scale_a_m2 <= 0.0)) {
        duty->command = (adcs_vec3_t){0, 0, 0};
        duty->saturated_axes = 0U;
        return ADCS_E_RANGE;
    }

    mask = 0U;
    vals[0] = requested_a_m2->x;
    vals[1] = requested_a_m2->y;
    vals[2] = requested_a_m2->z;

    for (i = 0; i < 3; i++) {
        d = vals[i] / full_scale_a_m2;

        if (d == 0.0) {
            /* |d| == 0 -> Output 0, promotion bit clear */
            out_mag = 0.0;
        } else {
            abs_d = fabs(d);

            if (abs_d < minimum_duty) {
                /* 0 < |d| < minimum_duty -> Output minimum_duty, promotion bit set */
                out_mag = minimum_duty;
                mask |= (unint32)(1U << i);
            } else if (abs_d > 1.0) {
                /* |d| > 1 -> Output 1, promotion bit clear */
                out_mag = 1.0;
            } else {
                /* minimum_duty <= |d| <= 1 -> Output |d|, promotion bit clear */
                out_mag = abs_d;
            }

            /* Restore the original sign */
            out_mag = copysign(out_mag, d);
        }

        /* Store result */
        switch(i) {
            case 0: cmd_vec.x = out_mag; break;
            case 1: cmd_vec.y = out_mag; break;
            case 2: cmd_vec.z = out_mag; break;
        }
    }

    duty->command = cmd_vec;
    duty->saturated_axes = mask;

    return ADCS_OK;
}

